+import Database from 'better-sqlite3'
+import { dirname, join } from 'node:path'
+import { fileURLToPath } from 'node:url'
+import { cart, categories, creators, DB_USER_ID, favorites, orders, prompts } from './seed'
+
+const root = dirname(dirname(dirname(fileURLToPath(import.meta.url))))
+const defaultPath = join(root, 'data', 'powerprompt.sqlite3')
+
+let connection: Database.Database | null = null
+
+export function getDb(path = process.env.POWERPROMPT_DB_PATH ?? defaultPath) {
+  if (!connection || connection.name !== path) {
+    connection = new Database(path)
+    connection.pragma('journal_mode = WAL')
+    migrate(connection)
+    seed(connection)
+  }
+  return connection
+}
+
+export function resetDbForTests(path = ':memory:') {
+  connection?.close()
+  connection = new Database(path)
+  migrate(connection)
+  seed(connection)
+  return connection
+}
+
+function migrate(db: Database.Database) {
+  db.exec(`
+    CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, name TEXT NOT NULL);
+    CREATE TABLE IF NOT EXISTS creators (id INTEGER PRIMARY KEY, name TEXT NOT NULL, handle TEXT NOT NULL, commission_rate REAL NOT NULL);
+    CREATE TABLE IF NOT EXISTS categories (name TEXT PRIMARY KEY);
+    CREATE TABLE IF NOT EXISTS prompts (
+      id INTEGER PRIMARY KEY,
+      title TEXT NOT NULL,
+      slug TEXT NOT NULL UNIQUE,
+      model TEXT NOT NULL,
+      category TEXT NOT NULL REFERENCES categories(name),
+      price_cents INTEGER NOT NULL,
+      sold INTEGER NOT NULL,
+      rating REAL NOT NULL,
+      creator_id INTEGER NOT NULL REFERENCES creators(id),
+      aspect_ratio TEXT NOT NULL,
+      image_url TEXT NOT NULL,
+      description TEXT NOT NULL,
+      created_at TEXT NOT NULL
+    );
+    CREATE TABLE IF NOT EXISTS favorites (user_id INTEGER NOT NULL, prompt_id INTEGER NOT NULL, PRIMARY KEY(user_id, prompt_id));
+    CREATE TABLE IF NOT EXISTS cart_items (user_id INTEGER NOT NULL, prompt_id INTEGER NOT NULL, qty INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(user_id, prompt_id));
+    CREATE TABLE IF NOT EXISTS orders (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, status TEXT NOT NULL, fee_cents INTEGER NOT NULL, created_at TEXT NOT NULL);
+    CREATE TABLE IF NOT EXISTS order_items (order_id INTEGER NOT NULL, prompt_id INTEGER NOT NULL, price_cents INTEGER NOT NULL, creator_id INTEGER NOT NULL);
+    CREATE TABLE IF NOT EXISTS visits (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, created_at TEXT NOT NULL);
+  `)
+}
+
+function seed(db: Database.Database) {
+  const seeded = db.prepare('SELECT COUNT(*) AS count FROM prompts').get() as { count: number }
+  if (seeded.count > 0) return
+  const insert = db.transaction(() => {
+    db.prepare('INSERT INTO users (id, name) VALUES (?, ?)').run(DB_USER_ID, 'Demo Buyer')
+    for (const category of categories) db.prepare('INSERT INTO categories (name) VALUES (?)').run(category)
+    for (const creator of creators) db.prepare('INSERT INTO creators VALUES (?, ?, ?, ?)').run(creator.id, creator.name, creator.handle, creator.commissionRate)
+    for (const prompt of prompts) {
+      db.prepare(`INSERT INTO prompts VALUES (@id, @title, @slug, @model, @category, @priceCents, @sold, @rating, @creatorId, @aspectRatio, @imageUrl, @description, @createdAt)`).run(prompt)
+    }
+    for (const promptId of favorites) db.prepare('INSERT INTO favorites VALUES (?, ?)').run(DB_USER_ID, promptId)
+    for (const promptId of cart) db.prepare('INSERT INTO cart_items VALUES (?, ?, 1)').run(DB_USER_ID, promptId)
+    for (let i = 0; i < 28; i += 1) db.prepare('INSERT INTO visits (user_id, created_at) VALUES (?, date(?, ?))').run(DB_USER_ID, '2026-07-01', `+${i % 7} day`)
+    for (const order of orders) {
+      const result = db.prepare('INSERT INTO orders (id, user_id, status, fee_cents, created_at) VALUES (?, ?, ?, ?, ?)').run(order.id, order.userId, order.status, order.feeCents, order.createdAt)
+      const orderId = Number(result.lastInsertRowid || order.id)
+      for (const promptId of order.items) {
+        const prompt = prompts.find((item) => item.id === promptId)
+        if (prompt) db.prepare('INSERT INTO order_items VALUES (?, ?, ?, ?)').run(orderId, prompt.id, prompt.priceCents, prompt.creatorId)
+      }
+    }
+  })
+  insert()
+}
*** End Patch

